#!/usr/bin/env python3
"""Deploy script: create all project files on server."""
import base64, os, sys

FILES = {
    ".env": "",
    "Dockerfile": "",
    "app/__init__.py": "",
    "app/config.py": "",
    "app/main.py": "",
    "app/routers/__init__.py": "",
    "app/routers/audit_log.py": "",
    "app/routers/auth.py": "",
    "app/routers/me.py": "",
    "app/routers/sync.py": "",
    "app/routers/sync_history.py": "",
    "app/routers/users.py": "",
    "app/services/__init__.py": "",
    "app/services/auth.py": "",
    "app/services/db.py": "",
    "app/services/jinlian_client.py": "",
    "app/services/qiwai_client.py": "",
    "app/services/sync_engine.py": "",
    "app/services/track_mapper.py": "",
    "app/static/index.html": "",
    "customers.yaml": "",
    "docker-compose.yml": "",
    "requirements.txt": "ZmFzdGFwaT49MC4xMTAuMAp1dmljb3JuW3N0YW5kYXJkXT49MC4yNy4wCmh0dHB4Pj0wLjI3LjAKYXBzY2hlZHVsZXI+PTMuMTAuNApweXlhbWw+PTYuMC4xCnB5dGhvbi1kb3RlbnY+PTEuMC4xCmJyb3RsaT49MS4xLjAKcHl0aG9uLW11bHRpcGFydD49MC4wLjkKcHlqd3Q+PTIuOC4wCmJjcnlwdD49NC4wLjAK",
}

DEST = "/opt/sync-service"
os.makedirs(DEST, exist_ok=True)
os.makedirs(os.path.join(DEST, "data"), exist_ok=True)
os.makedirs(os.path.join(DEST, "app", "static"), exist_ok=True)

for path, b64 in FILES.items():
    full = os.path.join(DEST, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "wb") as f:
        f.write(base64.b64decode(b64))
    print("  created:", path)

# Create empty favicon placeholder
fav = os.path.join(DEST, "app", "static", "favicon.jpg")
if not os.path.exists(fav):
    with open(fav, "wb") as f:
        f.write(b"")  # empty placeholder
    print("  created: app/static/favicon.jpg (placeholder)")

print()
print("Total:", len(FILES), "files created")
print()
print("Now run:")
print("  cd /opt/sync-service")
print("  chmod 600 .env")
print("  docker compose up -d --build")